// worker/talk/check.ts
/ 吹き出しの URL が、書いてよい URL だけか（extraUrls は終わりの / の有り無しを問わない） /
export function onlyAllowedUrls(text: string, allowedUrl: string | undefined, extraUrls: readonly string[] = []): boolean {
 const extra = new Set(extraUrls.map(trimSlash));
 return [...text.matchAll(URLINTEXT)].every((m) => m[0] === allowedUrl || extra.has(trimSlash(m[0])));
}
