// worker/talk/promo.ts
// PROMOPAUSEHOURS：この時間のうちに紹介していたら、一覧を渡さない
// PROMOSERVICEDAYS：この日数のうちに送ったサービスは、一覧から外す
// （値は運用しながら決めるので省略）

/ 送った返事から、渡す一覧を決める（純粋な関数） /
export function promoOfferFrom(services: readonly PromoService[], sent: readonly { text: string; createdAt: number }[], now: number): PromoOffer {
 let paused = false;
 const recent = new Set ();
 for (const m of sent) {
 const hits = servicesInText(services, m.text); // 文の中の URL に、どのサービスの URL があるか
 if (hits.length === 0) continue;
 if (m.createdAt >= now - PROMOPAUSEHOURS HOURMS) paused = true;
 if (m.createdAt >= now - PROMOSERVICEDAYS 24 HOURMS) for (const s of hits) recent.add(s.id);
 }
 if (paused) return { services: [], paused: true };
 const left = services.filter((s) => !recent.has(s.id));
 return { services: left, paused: left.length === 0 };
}
