// worker/index.ts
async scheduled(controller: ScheduledController, env: Env, ctx: ExecutionContext): Promise {
 ctx.waitUntil(runCron(env).catch((e: unknown) => console.error('cronfailed', e instanceof Error ? e.name : 'unknown')));
},

// worker/cron.ts（要点）
export async function runCron(env: Env): Promise {
 const now = nowMs(env); // DEVNOW で時刻を変えて試せる
 const date = jstDate(now);
 // 1. 今日の予定がまだ無いメンバーの予定を作る（日付が変わったあとの最初の回で作られる）
 const { results } = await env.DB.prepare(
 "SELECT c.id, c.profilejson FROM characters c WHERE c.status = 'active' AND NOT EXISTS (SELECT 1 FROM dailyschedules s WHERE s.characterid = c.id AND s.date = ?)",
 ).bind(date).all ();
 for (const row of results) {
 try {
 await ensureSchedule(env, parseCharacterProfile(JSON.parse(row.profilejson)), date, now);
 } catch (e) {
 console.error('cronschedulefailed', row.id, e instanceof Error ? e.name : 'unknown');
 }
 }
 await runDiaries(env, now); // 2. 日記を書く時刻からの窓の中で、まだ書いていない日
 try {
 await runSnsDrafts(env, now); // 3. 朝の決まった回だけ
 } catch (e) { / … / }
 try {
 await runSnsMails(env, now); // 4. 運営あての SNS の知らせ
 } catch (e) { / … / }
 // 5. …（ほかの定期処理）
 try {
 await purgeOldMessages(env, now); // 6. 日本時間の 4時台だけ
 } catch (e) { / … / }
}
