// worker/sns/cron.ts
export const SNSDRAFTAT = 6 60 + 5; // 0時からの分
const WINDOW = 5; // Cron は5分ごとなので、6:05〜6:09 の回だけ

export function isSnsDraftTime(now: number): boolean {
 const t = jstMinutes(now);
 return t >= SNSDRAFTAT && t < SNSDRAFTAT + WINDOW;
}
