// worker/lib/time.ts
/ 今（ミリ秒）。DEVNOW（ISO の日時）があり、PUBLICURL が http のときだけ、その時刻を今にする（開発用の時計） /
export function nowMs(env: Pick ): number {
 if (env.DEVNOW && env.PUBLICURL.startsWith('http:')) {
 const t = Date.parse(env.DEVNOW);
 if (Number.isFinite(t)) return t;
 }
 return Date.now();
}
